style:
/* 青函 —— 圆形头像配蓝色圆徽标题 */

.tw-qinghan.layout-profile.resume-paper .paper-header {
  margin-bottom: 6mm;
  padding-bottom: 4.4mm;
  border-bottom: 0.25mm solid #d9e6ee;
  align-items: center;
  gap: 7mm;
}

.tw-qinghan.layout-profile.resume-paper .paper-photo {
  order: -1;
  width: 28mm;
  height: 28mm;
  border: 1.4mm solid #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 0.3mm #d7e6ef;
  object-fit: cover;
}

.tw-qinghan.layout-profile.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #eff6fa;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-qinghan.layout-profile.resume-paper .paper-name {
  color: var(--paper-accent);
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.05);
  letter-spacing: 0.08em;
}

.tw-qinghan.layout-profile.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #6d7f89;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-qinghan.layout-profile.resume-paper .paper-role {
  margin-top: 1.4mm;
  color: #3d4c55;
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
}

.tw-qinghan.layout-profile.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 5mm;
  margin-top: 3mm;
  color: #33434c;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-qinghan.layout-profile.resume-paper .paper-contact {
  display: inline-flex;
  gap: 1.4mm;
}

.tw-qinghan.layout-profile.resume-paper .paper-contact + .paper-contact::before {
  content: "";
  left: -2.6mm;
  width: 0.2mm;
  height: 3.2mm;
  background: #dbe7ee;
  print-color-adjust: exact;
}

.tw-qinghan.layout-profile.resume-paper .paper-contact__label {
  color: #7f9099;
}

/* 标题：蓝色圆徽 + 蓝字 + 通栏细线 */
.tw-qinghan.layout-profile.resume-paper .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  margin-bottom: 3.2mm;
  padding-bottom: 1.4mm;
  border-bottom: 0.25mm solid #dbe7ee;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 1.08);
  letter-spacing: 0.08em;
}

.tw-qinghan.layout-profile.resume-paper .paper-section__icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 5.4mm;
  height: 5.4mm;
  border: none;
  border-radius: 50%;
  background: var(--paper-accent);
  color: #fff;
  print-color-adjust: exact;
}

.tw-qinghan.layout-profile.resume-paper .paper-section__icon svg {
  width: 58%;
  height: 58%;
}

.tw-qinghan.layout-profile.resume-paper .paper-style-line .paper-section__title span::before {
  display: none;
}

.tw-qinghan.layout-profile.resume-paper .paper-section__body {
  color: #303f47;
}

.tw-qinghan.layout-profile.resume-paper .paper-item-title {
  color: #1d2b33;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-qinghan.layout-profile.resume-paper .paper-item-period {
  color: #7b8d97;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-qinghan.layout-profile.resume-paper .paper-item-sub {
  color: #44535b;
}

.tw-qinghan.layout-profile.resume-paper .paper-rich ul,
.tw-qinghan.layout-profile.resume-paper .paper-rich ol {
  padding-left: 1.1em;
}

.tw-qinghan.layout-profile.resume-paper .paper-rich li::marker {
  color: var(--paper-accent);
}

/* 技能：两列，名称在左、熟练度在右 */
.tw-qinghan.layout-profile.resume-paper .paper-skills {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 2mm 12mm;
}

.tw-qinghan.layout-profile.resume-paper .paper-skill {
  padding-bottom: 1.2mm;
  border-bottom: 0.2mm solid #e3edf2;
}

.tw-qinghan.layout-profile.resume-paper .paper-skill__name {
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 400;
}

.tw-qinghan.layout-profile.resume-paper .paper-skill__dots {
  display: none;
}

.tw-qinghan.layout-profile.resume-paper .paper-skill__level {
  display: inline;
  color: #6b7d87;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-qinghan.layout-profile.resume-paper .paper-note__tag {
  color: #1d2b33;
  font-weight: 600;
}

/* 主修课程回到正文读法 */
.tw-qinghan.layout-profile.resume-paper .paper-note__tag {
  display: inline;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 0;
  background: none;
  color: #1d2b33;
  font-weight: 600;
  font-size: inherit;
}

.tw-qinghan.layout-profile.resume-paper .paper-note__tag::after {
  content: "：";
}

.tw-qinghan.layout-profile.resume-paper .paper-footer {
  border-top: 0.2mm solid #e2ecf2;
  color: #9dabb3;
}
